    'A synchronous script tag can impact your webpage\'s performance'
  ]
])

function replaceNextMessage(message) {
  const unwantedPolyfillioMatch = /^No duplicate polyfills from Polyfill\.io are allowed\. (.+) is already shipped with Next\.js\. See: https:\/\/nextjs\.org\/docs\/messages\/no-unwanted-polyfillio\.$/.exec(message)

  if (unwantedPolyfillioMatch) {
    return `You're requesting polyfills from polyfill.io which are already shipped with NextJS. Please remove ${unwantedPolyfillioMatch[1]} from the features list.`
  }

  return nextMessageReplacements.get(message) || message
}

function createContextWithPatchedReport(context) {
  const patchedContext = Object.create(context)

  Object.defineProperty(patchedContext, 'report', {
    value(...args) {
      if (args[0] && typeof args[0] === 'object' && typeof args[0].message === 'string') {
        context.report({
          ...args[0],
          message: replaceNextMessage(args[0].message)
        })
        return
      }

      if (typeof args[1] === 'string') {
        args[1] = replaceNextMessage(args[1])
      } else if (typeof args[2] === 'string') {
        args[2] = replaceNextMessage(args[2])
      }

      context.report(...args)
    }
  })

  return patchedContext
}

function patchNextRuleMessage(ruleName) {
  const rule = nextPlugin.rules[ruleName]

  if (typeof rule === 'function') {
    nextPlugin.rules[ruleName] = Object.assign(
      context => rule(createContextWithPatchedReport(context)),
      rule
    )
    return
  }

  nextPlugin.rules[ruleName] = {
    ...rule,
    create: context => rule.create(createContextWithPatchedReport(context))
  }
}

for (const ruleName of [
  'no-css-tags',
  'no-sync-scripts',
  'no-unwanted-polyfillio'
]) {
  patchNextRuleMessage(ruleName)
}

